    @Test fun keepsStylesAndLinksAcrossCursorSpacing() {
        val first = "  This paragraph describes the updated reading experience"
        val source = "\u001b[2C\u001b[1m" + first.drop(2).replace(" ", "\u001b[C") + "\u001b[0m\n\u001b[2C\u001b[31mcontinuing with \u001b]8;;https://example.com\u0007linked text\u001b]8;;\u0007 and https://example.org.\n" + "─".repeat(first.length + 2)
        val text = TerminalText.reflowParagraphs(TerminalText.parse(source))
        assertTrue(text.text.startsWith(first + " continuing with linked text"))
        val trimmed = TerminalText.trimLineEnds(text)
        for (block in terminalBlocks(trimmed)) {
            if (block.text.startsWith(first)) {
                assertEquals(1.2f.em, block.paragraphStyles.single().item.textIndent?.restLine)
                assertEquals(0.em, block.paragraphStyles.single().item.textIndent?.firstLine)
            }
        }
        val offset = text.text.indexOf("continuing")
        assertEquals(TerminalText.palette(1), text.spanStyles.first { offset in it.start until it.end }.item.color)
        val linked = text.text.indexOf("linked")
        assertTrue(text.getLinkAnnotations(linked, linked + 1).isNotEmpty())
        val url = text.text.indexOf("https://example.org")
        assertTrue(text.getLinkAnnotations(url, url + 1).isNotEmpty())
    }
